import json, urllib.request, urllib.error, urllib.parse
from pathlib import Path
tok = json.loads(Path("/home/box/sand-data/connector-secrets/2e892fe0-2e16-42ab-9684-76d8253cd433/Pagerduty-mcp.json").read_text())["PAGERDUTY_API_TOKEN"].strip()
if tok.lower().startswith("token "):
    tok = tok[6:].strip()

def get(url):
    req = urllib.request.Request(
        url,
        headers={
            "Authorization": f"Token {tok}",
            "Accept": "application/vnd.pagerduty+json;version=2",
            "User-Agent": "NetDoctor",
        },
    )
    with urllib.request.urlopen(req, timeout=20) as resp:
        return resp.status, json.loads(resp.read().decode())

try:
    status, data = get("https://api.pagerduty.com/incidents?limit=25&statuses%5B%5D=triggered&statuses%5B%5D=acknowledged")
    incidents = data.get("incidents") or []
    print(f"rest_status={status} open_count={len(incidents)} more={data.get('more')}")
    out=[]
    for i in incidents:
        out.append({
            "id": i.get("id"),
            "incident_number": i.get("incident_number"),
            "title": i.get("title"),
            "status": i.get("status"),
            "urgency": i.get("urgency"),
            "service": (i.get("service") or {}).get("summary"),
            "created_at": i.get("created_at"),
            "html_url": i.get("html_url"),
        })
    Path("/tmp/pd-open-incidents.json").write_text(json.dumps(out, indent=2))
    print("wrote /tmp/pd-open-incidents.json")
    # also try users/me to confirm identity without dumping email if possible
    try:
        st2, me = get("https://api.pagerduty.com/users/me")
        u = me.get("user") or {}
        print(f"me_status={st2} name={u.get('name')} role={u.get('role')} html_url={u.get('html_url')}")
    except Exception as e:
        print(f"me_error={type(e).__name__}")
except urllib.error.HTTPError as e:
    body = e.read(300).decode("utf-8","replace")
    print(f"rest_http_error={e.code} body={body[:300]}")
except Exception as e:
    print(f"rest_error={type(e).__name__}: {e}")
