  $active = aws cloudwatch get-metric-statistics --namespace AWS/NATGateway --metric-name ActiveConnectionCount --dimensions Name=NatGatewayId,Value=$n --start-time $startS --end-time $endS --period 1209600 --statistics Maximum --profile netaws --region us-west-2 --output json 2>$null | ConvertFrom-Json
